<?php defined( 'ABSPATH' ) || exit;
/**
 * Pest encyclopedia: CPT zad_pest at /pests/{slug}/ (the CPT's own rewrite rule — no page is generated by itself; no archive).
 * The owner writes the content; this file builds the structure: fields, identification attributes (used by the question-based identifier),
 * a single template, a [zad_pests] list shortcode for a normal Page, schema (Article + FAQPage on the theme's single @graph) and breadcrumbs.
 * Nothing is invented: an empty field prints nothing.
 */

/* ---------------------------------------------- settings ---------------------------------------------- */

